class NpcRelationshipMilestoneDefinition {
  const NpcRelationshipMilestoneDefinition({
    required this.dialogueNodeId,
    required this.seenFlagId,
  });

  final String dialogueNodeId;
  final String seenFlagId;

  factory NpcRelationshipMilestoneDefinition.fromJson(
    Map<String, Object?> json,
  ) {
    _exactKeys(json, const {'dialogueNodeId', 'seenFlagId'}, 'milestone');
    return NpcRelationshipMilestoneDefinition(
      dialogueNodeId: _string(json, 'dialogueNodeId'),
      seenFlagId: _string(json, 'seenFlagId'),
    );
  }
}

class NpcRelationshipDefinition {
  const NpcRelationshipDefinition({
    required this.levelOneAffinity,
    required this.levelOneLabel,
    this.levelOneMilestone,
  });

  static const mvpDefault = NpcRelationshipDefinition(
    levelOneAffinity: 3,
    levelOneLabel: 'Acquaintance',
  );

  final int levelOneAffinity;
  final String levelOneLabel;
  final NpcRelationshipMilestoneDefinition? levelOneMilestone;

  factory NpcRelationshipDefinition.fromJson(Map<String, Object?> json) {
    _exactKeysWithOptional(
      json,
      required: const {'levelOneAffinity', 'levelOneLabel'},
      optional: const {'levelOneMilestone'},
      path: 'relationship',
    );
    final levelOneAffinity = _int(json, 'levelOneAffinity');
    if (levelOneAffinity <= 0) {
      throw const FormatException(
        'levelOneAffinity must be a positive integer.',
      );
    }
    return NpcRelationshipDefinition(
      levelOneAffinity: levelOneAffinity,
      levelOneLabel: _string(json, 'levelOneLabel'),
      levelOneMilestone: json['levelOneMilestone'] == null
          ? null
          : NpcRelationshipMilestoneDefinition.fromJson(
              _object(json['levelOneMilestone'], 'levelOneMilestone'),
            ),
    );
  }

  int levelForAffinity(int affinity) {
    if (affinity < 0) {
      throw ArgumentError.value(
        affinity,
        'affinity',
        'Affinity cannot be negative.',
      );
    }
    return affinity >= levelOneAffinity ? 1 : 0;
  }

  String? labelForLevel(int level) {
    return switch (level) {
      0 => null,
      1 => levelOneLabel,
      _ => throw ArgumentError.value(
        level,
        'level',
        'Unknown relationship level.',
      ),
    };
  }
}

